\mathrm{df\text{-}countable\text{-}field}\vdash\;\begin{aligned}
\mathsf{Field}(\mathcal K)&\leftrightarrow\mathsf{Ring}(\mathcal K)\land\forall a\in K\;(a\ne0_K\to\exists b\in K\;a\cdot_Kb=1_K),\\
\mathsf{Subfield}(S,\mathcal K)&\leftrightarrow\mathsf{Field}(\mathcal K)\land S\subseteq K\land0_K,1_K\in S\\
&\quad\land(\forall a,b\in S\;(a+_Kb\in S\land a\cdot_Kb\in S\land-_Ka\in S))\\
&\quad\land\forall a\in S\;(a\ne0_K\to\exists b\in S\;a\cdot_Kb=1_K).
\end{aligned}
